const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const name = String(body.name ?? '').trim();
const email = String(body.email ?? '').trim().toLowerCase();
const message = String(body.message ?? '').trim();
if (!name || name.length > 120) throw new Error('O campo name é obrigatório e deve ter até 120 caracteres.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('O campo email é inválido.');
if (!message) throw new Error('O campo message é obrigatório.');
if (message.length > 5000) throw new Error('O campo message excede o limite de 5.000 caracteres.');
const now = new Date();
const requestId = `REQ-${now.toISOString().replace(/[-:.TZ]/g, '').slice(0, 14)}-${Math.random().toString(36).slice(2, 7).toUpperCase()}`;
return { json: { request_id: requestId, created_at: now.toISOString(), customer_name: name, customer_email: email, message } };

const request = $('Validar e normalizar solicitação').item.json;
const response = $json;
const safeCategories = new Set(['acesso', 'bug', 'duvida']);
const riskyCategories = new Set(['pagamento', 'privacidade', 'juridico', 'outro']);
let ai = null;
let failureReason = '';
try {
  const content = response?.choices?.[0]?.message?.content;
  if (!content) throw new Error(response?.error?.message || response?.error || 'Resposta vazia da IA.');
  ai = JSON.parse(content);
} catch (error) { failureReason = String(error.message || 'Falha ao interpretar resposta da IA.'); }
const validPriorities = new Set(['baixa', 'media', 'alta', 'urgente']);
const category = String(ai?.category ?? '').toLowerCase();
const priority = String(ai?.priority ?? '').toLowerCase();
const confidenceRaw = Number(ai?.confidence);
const confidence = Number.isFinite(confidenceRaw) ? Math.max(0, Math.min(1, confidenceRaw)) : 0;
const aiAvailable = Boolean(ai && safeCategories.has(category) || ai && riskyCategories.has(category));
const validAI = aiAvailable && validPriorities.has(priority) && typeof ai.summary === 'string' && typeof ai.draft_reply === 'string';
const finalCategory = validAI ? category : 'outro';
const finalPriority = validAI ? priority : 'alta';
const finalConfidence = validAI ? confidence : 0;
const needsHuman = !validAI || !safeCategories.has(finalCategory) || finalPriority === 'urgente' || finalConfidence < 0.75 || ai.needs_human_review === true;
const fallbackReply = 'Recebemos sua solicitação. Nossa equipe fará a análise e retornará assim que possível.';
const draftReply = validAI ? String(ai.draft_reply).trim().slice(0, 1500) : fallbackReply;
const reviewReason = !validAI ? (failureReason || 'Resposta da IA incompleta ou inválida.') : (String(ai.review_reason ?? '').trim() || (needsHuman ? 'Regra de segurança exige revisão humana.' : ''));
return { json: { ...request, category: finalCategory, priority: finalPriority, confidence: finalConfidence, summary: validAI ? String(ai.summary).trim().slice(0, 500) : 'Classificação automática indisponível; analisar solicitação manualmente.', draft_reply: draftReply, needs_human_review: needsHuman, review_reason: needsHuman ? reviewReason : '', approval_status: needsHuman ? 'PENDENTE' : 'AUTO_APROVADA', reviewer: '', review_notes: '', sent_at: '', ai_model: validAI ? 'gpt-4o-mini' : 'fallback-manual' } };

const item = { ...$json };
const normalized = String(item.message ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const signals = [
  { category: 'pagamento', pattern: /\b(pagamento|cobranca|fatura|estorno|reembolso|cartao|pix)\b/ },
  { category: 'privacidade', pattern: /\b(privacidade|lgpd|dados pessoais|vazamento|senha|acesso nao autorizado|dados expostos)\b/ },
  { category: 'juridico', pattern: /\b(advogado|juridic\w*|processo judicial|procon|acao judicial)\b/ },
  { category: 'urgencia', pattern: /\b(urgente|imediatamente|agora|hoje|emergencia|vazamento)\b/ }
];
const signal = signals.find((entry) => entry.pattern.test(normalized));
if (signal) {
  item.needs_human_review = true;
  item.approval_status = 'PENDENTE';
  item.review_reason = `Sinal determinístico de ${signal.category} no texto; revisão humana obrigatória.`;
}
return { json: item };
